import{_ as e,o,c as a,ai as r}from"./chunks/framework.CUYGB37K.js";const g=JSON.parse('{"title":"Product Attribute","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/attribute/product-attribute.md","filePath":"2.0/attribute/product-attribute.md","lastUpdated":1776149834000}'),s={name:"2.0/attribute/product-attribute.md"};function i(n,t,l,d,p,u){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="product-attribute" tabindex="-1">Product Attribute <a class="header-anchor" href="#product-attribute" aria-label="Permalink to &quot;Product Attribute&quot;">​</a></h1><p>An Attribute is a specification or characteristic of a product for example Color, Size, and Pattern an attribute of a T-Shirt.</p><p>You can create as many attributes for a single product. Product Attribute plays a major factor.</p><h3 id="how-to-create-a-product-attribute-in-unopim" tabindex="-1">How to Create a Product Attribute in UnoPim <a class="header-anchor" href="#how-to-create-a-product-attribute-in-unopim" aria-label="Permalink to &quot;How to Create a Product Attribute in UnoPim&quot;">​</a></h3><p>To Create UnoPim Attributes, open the Admin Panel and then follow the below steps.</p><h3 id="add-attributes" tabindex="-1">Add Attributes <a class="header-anchor" href="#add-attributes" aria-label="Permalink to &quot;Add Attributes&quot;">​</a></h3><p><strong>Step-1</strong> Click on <strong>Catalog</strong> &gt;&gt; <strong>Attributes</strong> &gt;&gt; <strong>Create Attributes</strong> as shown in the below image.</p><p><strong>Step-2</strong> Now enter the <strong>Code</strong> and <strong>Data Type</strong> inside the general section.</p><p><strong>Note -</strong> The <strong>Is Unique</strong> Validation is only available for Type - <strong>Text, Datetime &amp; Date</strong></p><p><strong>Step-3</strong> Enter the Label of your Attribute as shown in the below image.</p><p><strong>Step-4</strong> Select the Validation if you want to make your Attribute as a required field or Unique.</p><p><strong>Note -</strong> The <strong>Is Unique</strong> Validation is only available for Type - <strong>Text, Datetime &amp; Date</strong></p><p><strong>Step-5</strong> Select the field if you want to make the Attribute value as per the locale and value as per the channel.</p><p>Now, click on <strong>Save Attribute</strong> button and then the attribute is created successfully in the Datagrid.</p><p>Now <strong>Save the Attribute</strong> and then go to the Attribute Family from <strong>Catalog &gt;&gt; Attribute Families</strong> and assign it from the unassigned attribute by drag and drop at your desired place.</p><p>Now, <strong>Save Attribute Family</strong> and check the output while creating products on the product edit page.</p><h3 id="a-visual-breakdown-of-unopim-product-data-types" tabindex="-1">A Visual Breakdown of UnoPim Product Data Types <a class="header-anchor" href="#a-visual-breakdown-of-unopim-product-data-types" aria-label="Permalink to &quot;A Visual Breakdown of UnoPim Product Data Types&quot;">​</a></h3><p><strong>1) Text</strong> - A field that allows the user to enter a single line of text. It is typically used for short inputs like names, email addresses, or search queries.</p><p><strong>2) Textarea</strong> - A field that provides a larger area for users to input multi-line text. It&#39;s useful for longer responses or comments, such as descriptions or messages.</p><p>Additionally, you can Enable/Disable the Wysiwyg Editor.</p><p><strong>3) Boolean</strong> - Represents a true or false value. It&#39;s often used in forms to capture yes/no or on/off selections.</p><p><strong>4) Select</strong> - A dropdown menu that allows users to choose one option from a list. It&#39;s useful for making selections where only one option should be chosen from a predefined set of options.</p><p><strong>5) Multiselect</strong> - Similar to a select field but allows users to choose multiple options from a list. It&#39;s useful when multiple selections are valid and necessary.</p><p><strong>6) Datetime</strong> - A field that allows users to select a specific date and time. It&#39;s often used for scheduling or timestamping events.</p><p><strong>7) Date</strong> - A field that allows users to select or input a date only (without time). It&#39;s used for choosing a specific day in forms and calendars.</p><p><strong>8) Gallery</strong> - A Gallery attribute that allows managing and displaying multiple images and <strong>videos</strong> per product, enhancing the product media experience.</p><ol><li>The media attribute provides the ability to edit gallery images without changing their position.</li><li>Change the image position by dragging and dropping the gallery images.</li><li><strong>Video Support</strong> — You can now upload and manage video files in the gallery alongside images.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Video support in the gallery attribute was introduced in v1.0.0. You can upload common video formats directly to your product gallery.</p></div><p><strong>9) Image</strong> - A field for uploading or displaying image. Users can either upload an image file or view an image that&#39;s already been uploaded.</p><p><strong>10) File</strong> - A field that allows users to upload files. It can accept various file types, such as documents, images, or other file formats.</p><p><strong>11) Checkbox</strong> - A small box that can be checked or unchecked. It&#39;s used for binary choices, where a user can select or deselect an option, often used for agreements or preferences.</p><p><strong>12) Price</strong> - This input type is used to create price fields that are in addition to the predefined attributes: Prices.</p><h2 id="swatch-types" tabindex="-1">Swatch Types <a class="header-anchor" href="#swatch-types" aria-label="Permalink to &quot;Swatch Types&quot;">​</a></h2><p>UnoPim v2.0 introduces <strong>Swatch Types</strong> for <strong>Select</strong> and <strong>Multiselect</strong> attributes. Swatches provide a visual representation of attribute options, making it easier for users to identify and select values.</p><h3 id="types-of-swatches" tabindex="-1">Types of Swatches <a class="header-anchor" href="#types-of-swatches" aria-label="Permalink to &quot;Types of Swatches&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Swatch Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Dropdown</strong></td><td>Standard dropdown selection (default)</td></tr><tr><td><strong>Color</strong></td><td>Displays color swatches for each option</td></tr><tr><td><strong>Image</strong></td><td>Displays image thumbnails for each option</td></tr><tr><td><strong>Text</strong></td><td>Displays text labels as visual swatches</td></tr></tbody></table><h3 id="how-to-enable-swatch-types" tabindex="-1">How to Enable Swatch Types <a class="header-anchor" href="#how-to-enable-swatch-types" aria-label="Permalink to &quot;How to Enable Swatch Types&quot;">​</a></h3><ol><li>Create or edit a <strong>Select</strong> or <strong>Multiselect</strong> attribute</li><li>In the attribute configuration, select the <strong>Swatch Type</strong> from the dropdown</li><li>For each attribute option, configure the swatch value: <ul><li><strong>Color swatch</strong>: Enter a hex color code (e.g., <code>#FF0000</code> for red)</li><li><strong>Image swatch</strong>: Upload a small image for each option</li><li><strong>Text swatch</strong>: Enter display text for each option</li></ul></li><li>Click <strong>Save Attribute</strong></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Swatch types are especially useful for attributes like Color, Material, or Pattern where a visual representation helps users quickly identify options.</p></div><p>By following the above steps, you can easily create a <strong>Product Attribute</strong> in UnoPim.</p>',40)])])}const h=e(s,[["render",i]]);export{g as __pageData,h as default};
